insert into public.questions(id,bank_id,prompt,position,exam_metadata) values('c5200000-0000-4000-8000-000000000001','c5100000-0000-4000-8000-000000000001','毎朝、七時（　）起きます。',0,'{"subject":"grammar","type":"grammar_completion","prompt":"毎朝、七時（　）起きます。","tags":["time","particles"],"level":"n5","difficulty":"easy","source":"Original NihonPath demonstration draft — human review required"}'::jsonb) on conflict(id) do nothing;
