insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('c5200000-0000-4000-8000-000000000001','c5300000-0000-4000-8000-000000000001','に marks a specific time: 七時に means at seven o’clock.','「に」は動作が行われる時刻を表します。','I get up at seven every morning.') on conflict(question_id) do nothing;
