insert into public.questions(id,bank_id,prompt,position,exam_metadata) values('c5200000-0000-4000-8000-000000000006','c5100000-0000-4000-8000-000000000004','田中さんは何時に朝ご飯を食べますか。',5,'{"subject":"reading","type":"passage_reading","passage":"田中さんは毎朝六時に起きます。七時に朝ご飯を食べます。八時に会社へ行きます。","prompt":"田中さんは何時に朝ご飯を食べますか。","tags":["daily routine"],"level":"n5","difficulty":"easy","source":"Original NihonPath demonstration draft — human review required"}'::jsonb) on conflict(id) do nothing;
