insert into public.questions(id,bank_id,prompt,position,exam_metadata) values('c5200000-0000-4000-8000-000000000007','c5100000-0000-4000-8000-000000000004','土曜日、図書館は何時に開きますか。',6,'{"subject":"reading","type":"information_retrieval","passage":"図書館のお知らせ\n月曜日〜金曜日：午前九時〜午後六時\n土曜日：午前十時〜午後四時\n日曜日：休み","prompt":"土曜日、図書館は何時に開きますか。","tags":["opening hours"],"level":"n5","difficulty":"easy","source":"Original NihonPath demonstration draft — human review required"}'::jsonb) on conflict(id) do nothing;
